using System.Globalization;

namespace Noexs.Util;

public interface IPatternMatcher
{
    /// <returns>offset of the first match in <paramref name="buffer"/>, or -1</returns>
    int Match(ReadOnlySpan<byte> buffer);
}

/// <summary>
/// The Java version generated a JVM class per pattern with ASM. Runtime code generation is not
/// available under Native AOT, so the compiled form is a flat array of byte tests instead.
/// Bytes are compared unsigned (the generated bytecode compared signed bytes, so values
/// 0x80-0xFF could never match).
/// </summary>
public sealed class PatternCompiler
{
    public enum Condition
    {
        EQUALS,
        NOT_EQUALS,
        GREATER_THEN,
        LESS_THEN,
    }

    public sealed class PatternElement
    {
        public PatternElement(int value) : this(value, Condition.EQUALS)
        {
        }

        public PatternElement(int value, Condition condition)
        {
            Value = value;
            Condition = condition;
        }

        public int Value { get; }

        public Condition Condition { get; }

        public override string ToString()
        {
            return "PatternElement{value=" + Value + ", condition=" + Condition + '}';
        }
    }

    public IPatternMatcher Compile(PatternElement?[] pattern)
    {
        return new CompiledPattern(pattern);
    }

    private sealed class CompiledPattern : IPatternMatcher
    {
        private readonly int length;
        private readonly int[] offsets;
        private readonly int[] values;
        private readonly Condition[] conditions;

        public CompiledPattern(PatternElement?[] pattern)
        {
            length = pattern.Length;
            var tests = new List<(int offset, PatternElement e)>();
            for (int i = 0; i < pattern.Length; i++)
            {
                if (pattern[i] is { } e)
                {
                    tests.Add((i, e));
                }
            }
            offsets = tests.Select(t => t.offset).ToArray();
            values = tests.Select(t => t.e.Value).ToArray();
            conditions = tests.Select(t => t.e.Condition).ToArray();
        }

        public int Match(ReadOnlySpan<byte> buffer)
        {
            for (int pos = 0; buffer.Length - pos >= length; pos++)
            {
                if (Test(buffer, pos))
                {
                    return pos;
                }
            }
            return -1;
        }

        private bool Test(ReadOnlySpan<byte> buffer, int pos)
        {
            for (int i = 0; i < offsets.Length; i++)
            {
                int b = buffer[pos + offsets[i]];
                int v = values[i];
                bool ok = conditions[i] switch
                {
                    Condition.NOT_EQUALS => b != v,
                    Condition.GREATER_THEN => b > v,
                    Condition.LESS_THEN => b < v,
                    _ => b == v,
                };
                if (!ok)
                {
                    return false;
                }
            }
            return true;
        }
    }
}

public sealed class PatternTokenizer
{
    private sealed class Token
    {
        public TokenType Type;
        public int Width;
        public string Value = "";

        public override string ToString()
        {
            return "Token{type=" + Type + ", width=" + Width + ", value='" + Value + "'}";
        }
    }

    private enum TokenType
    {
        WILDCARD,
        WHITESPACE,
        OPERATOR,
        NUMERIC,
    }

    public PatternCompiler.PatternElement?[] Eval(string str)
    {
        List<Token> tokens = GetTokens(str);

        var res = new List<PatternCompiler.PatternElement?>();
        var condition = PatternCompiler.Condition.EQUALS;
        foreach (Token t in tokens)
        {
            if (t.Type == TokenType.OPERATOR)
            {
                switch (t.Value)
                {
                    case "!":
                        condition = PatternCompiler.Condition.NOT_EQUALS;
                        break;
                    case "<":
                        condition = PatternCompiler.Condition.LESS_THEN;
                        break;
                    case ">":
                        condition = PatternCompiler.Condition.GREATER_THEN;
                        break;
                }
            }
            else
            {
                if (t.Type == TokenType.NUMERIC)
                {
                    if (t.Width > 2)
                    {
                        throw new NotSupportedException("Value to high for a byte!");
                    }
                    res.Add(new PatternCompiler.PatternElement(
                        int.Parse(t.Value, NumberStyles.AllowHexSpecifier, CultureInfo.InvariantCulture), condition));
                }
                else if (t.Type == TokenType.WILDCARD)
                {
                    res.Add(null);
                }
                condition = PatternCompiler.Condition.EQUALS;
            }
        }
        return res.ToArray();
    }

    private static List<Token> GetTokens(string str)
    {
        ArgumentNullException.ThrowIfNull(str);
        var res = new List<Token>();
        bool ascii = false;
        foreach (char c in str)
        {
            if (c == '*')
            {
                ascii = !ascii;
                continue;
            }
            var t = new Token();
            if (!ascii)
            {
                t.Type = GetType(c);
                t.Width = 1;
                t.Value = c.ToString();
            }
            else
            {
                t.Type = TokenType.NUMERIC;
                t.Width = 2;
                t.Value = HexUtils.Pad('0', 2, (c & 0xFF).ToString("x"));
            }
            res.Add(t);
        }

        for (int i = 0; i < res.Count; i++)
        {
            Token t = res[i];
            Token? next = i + 1 < res.Count ? res[i + 1] : null;
            if (next != null)
            {
                if (t.Type == TokenType.NUMERIC && next.Type == TokenType.NUMERIC && t.Width < 2)
                {
                    t.Value += next.Value;
                    t.Width++;
                    res.RemoveAt(i + 1);
                    i--;
                }
                else if (t.Type == TokenType.WILDCARD && next.Type == TokenType.WILDCARD && t.Width < 2)
                {
                    t.Width++;
                    res.RemoveAt(i + 1);
                    i--;
                }
            }
        }

        res.RemoveAll(t => t.Type == TokenType.WHITESPACE);
        return res;
    }

    private static TokenType GetType(char c)
    {
        if (char.IsWhiteSpace(c))
        {
            return TokenType.WHITESPACE;
        }
        if (c is >= '0' and <= '9' or >= 'A' and <= 'Z' or >= 'a' and <= 'z')
        {
            return TokenType.NUMERIC;
        }
        return c switch
        {
            '<' or '>' or '!' => TokenType.OPERATOR,
            '?' => TokenType.WILDCARD,
            _ => throw new NotSupportedException("unsupported/invalid char:" + c),
        };
    }
}
